import sys
import json


def process(req):
    ebits = req["ebits"]
    fbits = req["fbits"]
    mode = req["mode"]
    pairs = req["pairs"]

    F = 1 << fbits
    fmask = F - 1
    Eall = (1 << ebits) - 1
    bias = (1 << (ebits - 1)) - 1
    emin = 1 - bias
    emax = Eall - 1 - bias
    w = 1 + ebits + fbits
    wmask = (1 << w) - 1

    nan_found = False
    invalid = False
    inf_mask = 0  # bit0: nonnegative inf product seen, bit1: negative inf product seen
    terms = []  # (sign, coeff, exp) for finite products; value = (-1)^sign * coeff * 2^exp

    for pa, pb in pairs:
        a = int(pa, 16) & wmask
        b = int(pb, 16) & wmask
        sa = a >> (ebits + fbits)
        ea = (a >> fbits) & Eall
        fa = a & fmask
        sb = b >> (ebits + fbits)
        eb = (b >> fbits) & Eall
        fb = b & fmask

        a_nan = ea == Eall and fa != 0
        b_nan = eb == Eall and fb != 0
        if a_nan or b_nan:
            nan_found = True
            # signaling iff top fraction bit is 0
            if a_nan and not (fa >> (fbits - 1)) & 1:
                invalid = True
            if b_nan and not (fb >> (fbits - 1)) & 1:
                invalid = True
            continue

        a_inf = ea == Eall  # fa == 0 here
        b_inf = eb == Eall
        if a_inf or b_inf:
            a_zero = ea == 0 and fa == 0
            b_zero = eb == 0 and fb == 0
            if a_zero or b_zero:
                invalid = True
            else:
                inf_mask |= 1 << (sa ^ sb)
            continue

        # both finite
        if ea == 0:
            ma = fa
            ta = 1 - bias - fbits
        else:
            ma = F + fa
            ta = ea - bias - fbits
        if eb == 0:
            mb = fb
            tb = 1 - bias - fbits
        else:
            mb = F + fb
            tb = eb - bias - fbits
        terms.append((sa ^ sb, ma * mb, ta + tb))

    if inf_mask == 3:
        invalid = True

    def out(bits, flags):
        return {"bits": format(bits, "0{}x".format((w + 3) // 4)), "flags": flags}

    if nan_found or invalid:
        bits = (Eall << fbits) | (1 << (fbits - 1))  # canonical NaN
        return out(bits, ["invalid"] if invalid else [])

    if inf_mask:
        s = 1 if inf_mask == 2 else 0
        return out((s << (ebits + fbits)) | (Eall << fbits), [])

    # exact finite accumulation
    if terms:
        k = min(t[2] for t in terms)
        total = 0
        for s, m, t in terms:
            v = m << (t - k)
            total = total - v if s else total + v
    else:
        k = 0
        total = 0

    if total == 0:
        neg = (mode == "RDN") or (
            len(terms) > 0 and all(m == 0 and s == 1 for s, m, _ in terms)
        )
        return out((1 << (ebits + fbits)) if neg else 0, [])

    sign = 1 if total < 0 else 0
    mag = -total if sign else total
    L = mag.bit_length() - 1 + k
    qe = L - fbits
    if qe < emin - fbits:
        qe = emin - fbits

    shift = qe - k
    if shift <= 0:
        N = mag << (-shift)
        inexact = False
    else:
        q = mag >> shift
        r = mag & ((1 << shift) - 1)
        inexact = r != 0
        if mode == "RNE":
            half = 1 << (shift - 1)
            up = r > half or (r == half and (q & 1))
        elif mode == "RNA":
            up = r >= (1 << (shift - 1))
        elif mode == "RTZ":
            up = False
        elif mode == "RUP":
            up = sign == 0 and inexact
        elif mode == "RDN":
            up = sign == 1 and inexact
        else:
            raise ValueError("unknown mode")
        N = q + 1 if up else q

    diff = emax + 1 - qe
    overflow = True if diff <= 0 else (N >= (1 << diff))
    if overflow:
        away = (
            mode in ("RNE", "RNA")
            or (mode == "RUP" and sign == 0)
            or (mode == "RDN" and sign == 1)
        )
        if away:
            bits = (sign << (ebits + fbits)) | (Eall << fbits)
        else:
            bits = (sign << (ebits + fbits)) | ((Eall - 1) << fbits) | fmask
        return out(bits, ["overflow", "inexact"])

    flags = []
    if inexact and (N == 0 or N.bit_length() - 1 + qe < emin):
        flags.append("underflow")
    if inexact:
        flags.append("inexact")

    if N == 0:
        bits = sign << (ebits + fbits)
    else:
        p = N.bit_length() - 1
        E = p + qe
        if E >= emin:
            if p <= fbits:
                sig = N << (fbits - p)
            else:  # carry: N == 2^(fbits+1)
                sig = N >> (p - fbits)
            bits = (sign << (ebits + fbits)) | ((E + bias) << fbits) | (sig - F)
        else:
            bits = (sign << (ebits + fbits)) | N
    return out(bits, flags)


def main():
    write = sys.stdout.write
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        write(json.dumps(process(json.loads(line))) + "\n")
    sys.stdout.flush()


if __name__ == "__main__":
    main()
